sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    var tableSysId = current.sys_id;
    var attachmentPayload = JSON.parse(current.attachment);

    for (var i = 0; i < attachmentPayload.length; i++) {

        var fileName = attachmentPayload[i].Email_Attachment_Name; //Email_Attachment_Name from JSON payload
        var emailAttachmentContent = attachmentPayload[i].Email_Attachment_Content; //Email_Attachment_Content from JSON payload
        var fileFormat = attachmentPayload[i].Email_Attachment_Name.split('.')[1];

        var attachment = new GlideSysAttachment();

        var rec = new GlideRecord('x_hsb11_hsbcmss_eh_hsbc_email_log');
        rec.get(tableSysId);
        var contentType = 'application/'+ fileFormat;
        var base64Encodedcontent = emailAttachmentContent;

        var agr = attachment.writeBase64(rec, fileName, contentType, base64Encodedcontent);

    } //End of For Loop
